// ---- lifecycle tests (docs/syntax-2.0.md §7.1) ----------------
// A `lifecycle test` drives the composition on a live stc-go
// context: load components, call through provision keys, unload
// LIFO, and assert no residue (R4 registry + R1 host resources).
type revlOptPair[T any] struct {
	value T
	ok    bool
}

func revlEq(a, b any) bool { return reflect.DeepEqual(a, b) }

func TestAnEveryTimerFiresOnEachAdvancedTick(revlT *testing.T) {
	root := stc.New()
	_fibers := map[string]*stc.Fiber{}
	RevlClockReset()
	{
		_f := LoadTickCounter(root)
		if err := _f.Ready(stdctx.Background()); err != nil {
			revlT.Fatalf("%s: %v", "lifecycle test \"an every-timer fires on each advanced tick\": load TickCounter", err)
		}
		_fibers["TickCounter"] = _f
	}
	{
		_f := LoadHeartbeat(root)
		if err := _f.Ready(stdctx.Background()); err != nil {
			revlT.Fatalf("%s: %v", "lifecycle test \"an every-timer fires on each advanced tick\": load Heartbeat", err)
		}
		_fibers["Heartbeat"] = _f
	}
	var before int64
	{
		_svc, _err := stc.Service[Counter](root, _keyCounter)
		if _err != nil {
			revlT.Fatalf("%s: %v", "lifecycle test \"an every-timer fires on each advanced tick\": counter is ACTIVE (R2)", _err)
		}
		before = (_svc).Count()
	}
	if !(before == 0) {
		revlT.Fatalf("lifecycle test \"an every-timer fires on each advanced tick\": assertion failed")
	}
	RevlClockAdvance(35000)
	var ticks int64
	{
		_svc, _err := stc.Service[Counter](root, _keyCounter)
		if _err != nil {
			revlT.Fatalf("%s: %v", "lifecycle test \"an every-timer fires on each advanced tick\": counter is ACTIVE (R2)", _err)
		}
		ticks = (_svc).Count()
	}
	if !(ticks == 3) {
		revlT.Fatalf("lifecycle test \"an every-timer fires on each advanced tick\": assertion failed")
	}
	if _f, _ok := _fibers["Heartbeat"]; _ok {
		_f.Dispose()
		// disposal is orchestrated asynchronously; a
		// reload must not collide with the old fiber's
		// provisions, so wait for it to be Gone
		for i := 0; i < 200 && _f.State() != stc.StateGone; i++ {
			time.Sleep(5 * time.Millisecond)
		}
		delete(_fibers, "Heartbeat")
	}
	RevlClockAdvance(100000)
	var settled int64
	{
		_svc, _err := stc.Service[Counter](root, _keyCounter)
		if _err != nil {
			revlT.Fatalf("%s: %v", "lifecycle test \"an every-timer fires on each advanced tick\": counter is ACTIVE (R2)", _err)
		}
		settled = (_svc).Count()
	}
	if !(settled == 3) {
		revlT.Fatalf("lifecycle test \"an every-timer fires on each advanced tick\": assertion failed")
	}
	if _f, _ok := _fibers["TickCounter"]; _ok {
		_f.Dispose()
		// disposal is orchestrated asynchronously; a
		// reload must not collide with the old fiber's
		// provisions, so wait for it to be Gone
		for i := 0; i < 200 && _f.State() != stc.StateGone; i++ {
			time.Sleep(5 * time.Millisecond)
		}
		delete(_fibers, "TickCounter")
	}
	// R4 + R1: the composition must leave the live
	// runtime holding nothing — the orchestrator reaps
	// disposed fibers asynchronously, so poll briefly.
	for i := 0; i < 200; i++ {
		if len(root.Fibers()) == 0 && revlHostLive() == 0 {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	if !(len(root.Fibers()) == 0 && revlHostLive() == 0) {
		revlT.Fatalf("lifecycle test \"an every-timer fires on each advanced tick\": residue \u2014 %d fiber(s), %d host resource(s) (R4/R1)", len(root.Fibers()), revlHostLive())
	}
}

